# Sources for the raga lesson (lessons/ragas.qmd, kind `raga` in apps/shared/lessons/tuning-kit.js).
# Checked 2026-11-27 against The Garland Encyclopedia of World Music, vol. 5 (page numbers as printed).
# Garland does NOT give: Yaman / Bhupali / Malkauns / Khamaj ascents and descents, any vadi / samvadi pair except
# Darbari Kanada and Jaunpuri, times of day for the six ragas, meend, kan, andolan on Bhairav or Todi.
P = ["lessons/ragas.qmd"]
SOURCES = [
    book('Ruckert, George, and Richard Widdess. "Hindustani Raga." *The Garland Encyclopedia of World Music*, vol. 5, *South Asia: The Indian Subcontinent*, edited by Alison Arnold, Garland, 2000, pp. 64-88.', P,
        note="Pp. 66-69 (a raga is a mode, neither tune nor scale; shruti and svara, 22 shrutis of doubtful relevance today; drone Sa and Pa, Ma or Ni when Pa is absent; that and aroh / avaroh; vadi 'speaker' and samvadi 'co-speaker', often a fourth or fifth apart, and the problems of the theory; pakad; rasa; time theory), p. 74 (Ali Akbar Khan's king and prime minister), pp. 78-79 (Bhatkhande's ten that, Fig. 5; Bhupali between Kalyan and Bilaval), pp. 79-81 (Fig. 6 ragas in letter notation: Bhairav, dawn), p. 82 (andolan, 'natural' tuning similar to Pythagorean, slides)."),
    book('Kassebaum, Gayathri Rajapur. "Karnatak Raga." *The Garland Encyclopedia of World Music*, vol. 5, *South Asia: The Indian Subcontinent*, edited by Alison Arnold, Garland, 2000, pp. 89-109.', P,
        note="P. 93 (22 shrutis, unequal), p. 97 (Venkatamakhi's 72 mela / melakarta)."),
    book('Wade, Bonnie C. "Hindustani Vocal Music." *The Garland Encyclopedia of World Music*, vol. 5, *South Asia: The Indian Subcontinent*, edited by Alison Arnold, Garland, 2000, pp. 162-87.', P,
        note="Pp. 180-81 (thumri ragas such as Khamaj: raised seventh going up, lowered coming down)."),
]
